defmodule AgentFn.Debug.EchoArgs do
  @moduledoc "Echo run/1 args for debugging passthrough."
  @behaviour AgentFn.Tool

  @spec run(map()) :: {:ok, map()} | {:error, String.t()}
  def run(args) when is_map(args) do
    {:ok, %{keys: Map.keys(args), has_description: Map.has_key?(args, "description") or Map.has_key?(args, :description), args: args}}
  end
end
